{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana maximum allowable rent increase","requirement":"A landlord may raise rent each year by no more than 3% of the current rent or 80% of the Consumer Price Index change, whichever is less; the maximum allowable increase is 2.87% for September 1, 2026 through August 31, 2027.","key_value":"lesser of 3% or 80% of CPI; 2.87% for September 1, 2026 through August 31, 2027","coverage_conditions":null,"applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2026-09-01","valid_through":"2027-08-31","citation":"Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"Your landlord can only raise your rent by a certain amount each year. The increase cannot be more than 3% of your current rent or 80% of the Consumer Price Index (CPI) change, whichever is less.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana just cause eviction requirement","requirement":"A landlord must have a valid reason to evict, such as nonpayment of rent, breaking the lease, or the owner moving into the property; for certain eviction reasons the landlord may owe relocation assistance.","key_value":null,"coverage_conditions":null,"applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"Your landlord must have a valid reason to evict you. This could be for not paying rent, breaking the lease, or if the landlord wants to move into the property themselves.","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
